let progressView='training',exerciseSelection='',progressRange=90,exerciseMetric='weight';
const exerciseKey=row=>typeof row==='object'&&row?.catalogId?row.catalogId:String(typeof row==='object'?row?.exercise:row||'').trim().toLowerCase().replace(/\s+/g,' ');
const workSets=session=>session.sets.filter(s=>s.done!==false&&s.type!=='warmup');
const setVolume=s=>(window.mfdTracking?.(s)||s.tracking)!=='assisted_bodyweight'&&Number.isFinite(s.kg)&&s.kg>0&&Number.isFinite(s.reps)&&s.reps>0?s.kg*s.reps:0;
function sessionTime(s){return Number.isFinite(s.started)?s.started:new Date(s.date+'T12:00:00').getTime()}
function selectedSessions(){let cutoff=progressRange?Date.now()-progressRange*86400000:0;return state.sessions.filter(s=>sessionTime(s)>=cutoff).sort((a,b)=>sessionTime(a)-sessionTime(b))}
function exerciseList(){let map=new Map();state.sessions.forEach(session=>session.sets.forEach(s=>{if(s.done!==false&&!map.has(exerciseKey(s)))map.set(exerciseKey(s),s.exercise)}));return [...map.entries()].sort((a,b)=>a[1].localeCompare(b[1]))}
function exerciseSessions(key,sessions=selectedSessions()){return sessions.map(s=>({session:s,sets:workSets(s).filter(x=>exerciseKey(x)===key)})).filter(x=>x.sets.length)}
function metricValue(sets,metric){let values=sets.map(s=>metric==='weight'&&(window.mfdTracking?.(s)||s.tracking)!=='assisted_bodyweight'?s.kg:metric==='reps'?s.reps:metric==='distance'?s.distance_meters:metric==='time'?s.duration_seconds:null).filter(v=>Number.isFinite(v));if(metric==='volume'){let valid=sets.some(s=>setVolume(s)>0);return valid?sets.reduce((v,s)=>v+setVolume(s),0):null}return values.length?Math.max(...values):null}
function numberText(n){return n==null?'—':(Math.round(n*10)/10).toLocaleString()}
function trainingChart(points,label,unit){let valid=points.filter(p=>p.value!=null);if(!valid.length)return `<div class="empty"><strong>No ${label.toLowerCase()} data yet.</strong>Log or import matching completed working sets to see this chart.</div>`;let max=Math.max(...valid.map(p=>p.value)),min=Math.min(...valid.map(p=>p.value)),pad=(max-min)*.15||Math.max(max*.1,1);min=Math.max(0,min-pad);max+=pad;let first=Math.min(...valid.map(p=>p.time)),last=Math.max(...valid.map(p=>p.time));let xy=valid.map(p=>({x:first===last?300:52+(p.time-first)/(last-first)*500,y:155-(p.value-min)/(max-min)*125,...p}));return `<svg viewBox="0 0 600 200" class="chart" role="img" aria-label="${esc(label)} chart in ${unit}, ${valid.length} sessions">${[0,1,2].map(i=>`<line x1="52" x2="552" y1="${30+i*62.5}" y2="${30+i*62.5}" stroke="#e9eee9"/><text x="2" y="${34+i*62.5}">${numberText(max-(max-min)*i/2)}</text>`).join('')}<polyline points="${xy.map(p=>p.x+','+p.y).join(' ')}" fill="none" stroke="#378063" stroke-width="2.5"/>${xy.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4" fill="#378063"><title>${p.date}: ${numberText(p.value)} ${unit}</title></circle>`).join('')}<text x="52" y="190">${dateText(valid[0].date)}</text><text x="510" y="190">${dateText(valid.at(-1).date)}</text></svg>`}
function progressPage(){let nav=`<div class="tabs"><button class="tab ${progressView==='training'?'active':''}" onclick="progressView='training';render()">Training progress</button><button class="tab ${progressView==='body'?'active':''}" onclick="progressView='body';render()">Body & recovery</button></div>`;if(progressView==='body')return nav+bodyProgressPage();let list=exerciseList(),sessions=selectedSessions(),sets=sessions.flatMap(workSets),volume=sets.reduce((n,s)=>n+setVolume(s),0);if(!list.some(([key])=>key===exerciseSelection))exerciseSelection=list[0]?.[0]||'';let history=exerciseSessions(exerciseSelection),allHistory=exerciseSessions(exerciseSelection,state.sessions.slice().sort((a,b)=>sessionTime(a)-sessionTime(b))),allSets=allHistory.flatMap(x=>x.sets),metrics=[['weight','Heaviest set','kg'],['volume','Session volume','kg·reps'],['reps','Most reps in a set','reps'],['distance','Longest distance in a set','m'],['time','Longest duration in a set','s']];return title('Make progress visible','Your training story.','Real records. Clear trends. One session at a time.',`<button class="btn secondary" onclick="openHevyImport()">↓ Import Hevy CSV</button>`)+nav+`<div class="progress-toolbar"><span class="small-muted">Show training from</span><div class="tabs">${[[30,'30 days'],[90,'90 days'],[365,'1 year'],[0,'All time']].map(([days,t])=>`<button class="tab ${progressRange===days?'active':''}" onclick="progressRange=${days};render()">${t}</button>`).join('')}</div></div>${!state.sessions.length?`<div class="card progress-empty"><span>↗</span><h2>Your history makes this personal.</h2><p>Import your Hevy CSV or complete a workout to see exercise trends, records, and weekly volume.</p><button class="btn" onclick="openHevyImport()">Import your workouts</button><button class="text-btn full" onclick="go('workouts')">Or start a workout →</button></div>`:`${state.sessions.some(s=>s.sample)?'<div class="section-note">Sample workouts are included and labeled in history. Records and charts reflect all logged data, including samples.</div>':''}<div class="grid stats"><div class="card"><div class="stat-head">Sessions in period</div><div class="stat-value">${sessions.length}</div><div class="stat-foot">Your selected date range</div></div><div class="card"><div class="stat-head">Working sets</div><div class="stat-value">${sets.length}</div><div class="stat-foot">Warm-up sets excluded</div></div><div class="card"><div class="stat-head">External load volume</div><div class="stat-value">${numberText(volume)}<small>kg·reps</small></div><div class="stat-foot">Weighted rep sets only</div></div><div class="card"><div class="stat-head">Training time</div><div class="stat-value">${numberText(sessions.reduce((n,s)=>n+(Number.isFinite(s.finished-s.started)?Math.max(0,s.finished-s.started)/60000:0),0))}<small>min</small></div><div class="stat-foot">Total recorded session duration</div></div></div><div class="card" style="margin-bottom:20px"><div class="card-head"><h2>Weekly training volume</h2><span class="small-muted">Working sets · kg × reps</span></div>${weeklyVolumeChart(sessions)}<p class="small-muted">Weeks begin Monday, based on logged workout dates. Bodyweight-only, timed, and distance sets don’t contribute to external load volume. No logged volume is shown as zero.</p></div><div class="card"><div class="card-head"><h2>Explore an exercise</h2><span class="small-muted">Names match exactly; variations stay separate</span></div><label for="progress-exercise">Exercise</label><select id="progress-exercise" onchange="exerciseSelection=this.value;render()">${list.map(([key,name])=>`<option value="${esc(key)}" ${key===exerciseSelection?'selected':''}>${esc(name)}</option>`).join('')}</select><div class="record-grid">${metrics.filter(([key])=>key!=='volume').map(([key,t,unit])=>`<div><span>${t}</span><strong>${numberText(metricValue(allSets,key))}<small> ${unit}</small></strong></div>`).join('')}</div><p class="small-muted">Records are all-time maxima from completed working sets. Longest duration is not a speed or performance ranking. Weights are shown exactly as logged.</p><div class="tabs metric-tabs">${metrics.map(([key,t])=>`<button class="tab ${exerciseMetric===key?'active':''}" onclick="exerciseMetric='${key}';render()">${t}</button>`).join('')}</div>${trainingChart(history.map(x=>({date:x.session.date,time:sessionTime(x.session),value:metricValue(x.sets,exerciseMetric)})),metrics.find(x=>x[0]===exerciseMetric)[1],metrics.find(x=>x[0]===exerciseMetric)[2])}<div class="card-head" style="margin-top:25px"><h2>Exercise history</h2><span class="small-muted">${history.length} sessions in range</span></div>${history.length?history.slice().reverse().map(({session:s,sets:rows})=>`<button class="exercise-history-row" onclick="sessionDetail('${s.id}')"><span><strong>${esc(s.name)}${s.sample?' · sample':''}</strong><small>${s.date} · ${rows.length} working sets</small></span><span>${rows.slice(0,3).map(setPerformance).map(esc).join(' / ')}${rows.length>3?' …':''}<small>View session →</small></span></button>`).join(''):'<div class="empty">No working sets for this exercise in the selected period.</div>'}</div>`}`}
function setPerformance(s){return [s.kg!=null?numberText(s.kg)+' kg':null,s.reps!=null?s.reps+' reps':null,s.duration_seconds!=null?formatRest(s.duration_seconds):null,s.distance_meters!=null?numberText(s.distance_meters)+' m':null].filter(x=>x!==null).join(' × ')}
function mondayKey(date){let d=new Date(date+'T12:00:00Z'),day=(d.getUTCDay()+6)%7;d.setUTCDate(d.getUTCDate()-day);return d.toISOString().slice(0,10)}
function weeklyVolume(sessions){if(!sessions.length)return [];let map=new Map();sessions.forEach(s=>{let week=mondayKey(s.date);map.set(week,(map.get(week)||0)+workSets(s).reduce((v,x)=>v+setVolume(x),0))});let keys=[...map.keys()].sort(),start=new Date(keys[0]+'T12:00:00Z'),end=new Date(keys.at(-1)+'T12:00:00Z'),rows=[];for(let d=new Date(start);d<=end;d.setUTCDate(d.getUTCDate()+7)){let key=d.toISOString().slice(0,10);rows.push({date:key,time:d.getTime(),value:map.get(key)||0})}return rows}
function weeklyVolumeChart(sessions){let weeks=weeklyVolume(sessions);if(!weeks.length)return '<div class="empty">No sessions in this date range.</div>';let max=Math.max(...weeks.map(x=>x.value),1),step=500/weeks.length;return `<svg viewBox="0 0 600 200" class="chart" role="img" aria-label="Weekly external load volume in kilograms times repetitions">${[0,1,2].map(i=>`<line x1="52" x2="552" y1="${30+i*62.5}" y2="${30+i*62.5}" stroke="#edf1ed"/><text x="2" y="${34+i*62.5}">${numberText(max*(1-i/2))}</text>`).join('')}${weeks.map((w,i)=>{let height=w.value/max*125;return `<rect x="${52+i*step+step*.12}" y="${155-height}" width="${Math.max(.5,step*.76)}" height="${height}" rx="2" fill="#89b39a"><title>Week of ${w.date}: ${numberText(w.value)} kg·reps</title></rect>`}).join('')}<text x="52" y="190">${dateText(weeks[0].date)}</text><text x="505" y="190">${dateText(weeks.at(-1).date)}</text></svg>`}
function previousSetHint(current,index){let active=state.active;if(!active)return '';let key=exerciseKey(current),past=state.sessions.filter(s=>sessionTime(s)<active.started&&s.sets.some(x=>exerciseKey(x)===key)).sort((a,b)=>sessionTime(b)-sessionTime(a))[0];if(!past)return '<div class="previous-set">Previous: no earlier session logged for this exercise.</div>';let type=current.type||'normal',matching=past.sets.filter(s=>exerciseKey(s)===key&&(s.type||'normal')===type),ordinal=active.sets.slice(0,index+1).filter(s=>s.group===current.group&&(s.type||'normal')===type).length-1,previous=matching[ordinal];if(!previous)return `<div class="previous-set">${past.date}: no matching ${esc(type)} set ${ordinal+1}.</div>`;return `<div class="previous-set"><span>Previous · ${past.date}${past.sample?' · sample':''}</span><strong>${esc(setPerformance(previous))}${previous.rpe!=null?' · RPE '+previous.rpe:''}</strong><button class="text-btn" onclick="copyPreviousSet(${index})">Use values</button></div>`}
function copyPreviousSet(index){let active=state.active,current=active.sets[index],key=exerciseKey(current),past=state.sessions.filter(s=>sessionTime(s)<active.started&&s.sets.some(x=>exerciseKey(x)===key)).sort((a,b)=>sessionTime(b)-sessionTime(a))[0];if(!past)return;let type=current.type||'normal',ordinal=active.sets.slice(0,index+1).filter(s=>s.group===current.group&&(s.type||'normal')===type).length-1,previous=past.sets.filter(s=>exerciseKey(s)===key&&(s.type||'normal')===type)[ordinal];if(!previous)return;for(let k of ['kg','reps','duration_seconds','distance_meters','custom_metric'])current[k]=previous[k]??null;current.tracking=setTracking(previous);current.rpe=null;current.done=false;save();render();toast('Previous values copied · log today’s effort when ready')}
render();
